alter table public.service_landings drop constraint if exists service_landings_slug_check;
alter table public.service_landings add constraint service_landings_slug_check check (
  slug in ('led-indoor', 'videotron-outdoor', 'rental-led', 'media-konvensional', 'digital-signage', 'event-production')
);

insert into public.service_landings (
  slug, content_id, content_en, seo_title_id, seo_description_id, seo_title_en, seo_description_en
) values
(
  'digital-signage',
  '{"eyebrow":"Layanan digital signage","title":"Digital Signage untuk Pengalaman Brand yang Terhubung","description":"Solusi display terhubung untuk retail, hospitality, wayfinding, dan ruang bermerek dengan perencanaan konten, lokasi, dan operasional yang selaras.","intro_eyebrow":"Dasar perencanaan","intro_title":"Solusi mengikuti alur audiens dan ruang.","intro":"Digital signage perlu direncanakan dari alur audiens, jarak pandang, pencahayaan, sumber konten, koneksi jaringan, dan akses pemeliharaan. Sistem disusun agar pesan dapat tampil konsisten dan mudah dikelola.","considerations_title":"Yang perlu dipastikan","considerations":["Alur audiens dan jarak pandang","Format konten serta jadwal pembaruan","Jalur listrik, jaringan, dan sistem pengelolaan","Struktur pemasangan serta akses perawatan"],"process_eyebrow":"Alur kerja","process_title":"Tahapan yang disesuaikan dengan proyek.","process":["Memahami kebutuhan ruang dan audiens","Menentukan layar serta format tampilan","Merencanakan konten dan sistem pengelolaan","Pemasangan, pengujian, dan serah terima"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Diskusikan kebutuhan media Anda.","cta_description":"Sampaikan lokasi, alur audiens, jenis konten, dan cara sistem akan digunakan agar konfigurasi dapat dibahas berdasarkan kebutuhan proyek.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"}'::jsonb,
  '{"eyebrow":"Digital signage service","title":"Digital Signage for Connected Brand Experiences","description":"Connected display solutions for retail, hospitality, wayfinding, and branded spaces, planned around content, placement, and daily operations.","intro_eyebrow":"Planning basis","intro_title":"A solution shaped by the audience and space.","intro":"Digital signage needs to account for audience flow, viewing distance, ambient light, content sources, network connections, and maintenance access. The system is shaped to keep messages consistent and easy to manage.","considerations_title":"What to confirm","considerations":["Audience flow and viewing distance","Content formats and update frequency","Power, network, and content management routes","Mounting and maintenance access"],"process_eyebrow":"Workflow","process_title":"Stages adapted to the project.","process":["Reviewing the space and audience needs","Selecting displays and formats","Planning content and management systems","Installation, testing, and handover"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Discuss your media requirements.","cta_description":"Share the location, audience flow, content type, and intended use so the configuration can be discussed around your project.","cta_button_text":"Contact Visitiga","back_text":"All services"}'::jsonb,
  'Digital Signage untuk Pengalaman Brand | Visitiga', 'Solusi display terhubung untuk retail, hospitality, wayfinding, dan ruang bermerek.',
  'Digital Signage for Connected Brand Experiences | Visitiga', 'Connected display solutions for retail, hospitality, wayfinding, and branded spaces.'
),
(
  'event-production',
  '{"eyebrow":"Layanan event production","title":"Event Production untuk Pengalaman Visual Live","description":"Dukungan produksi visual dan teknis untuk acara, panggung, konferensi, dan pengalaman live dengan persiapan yang terukur dari rundown hingga hari pelaksanaan.","intro_eyebrow":"Dasar perencanaan","intro_title":"Solusi mengikuti karakter acara.","intro":"Produksi acara perlu menyatukan kebutuhan visual, panggung, sinyal, listrik, jadwal loading, dan dukungan teknis. Perencanaan dibuat berdasarkan venue dan alur acara agar eksekusi berjalan terkoordinasi.","considerations_title":"Yang perlu dipastikan","considerations":["Format acara dan tata letak audiens","Kebutuhan panggung, layar, dan visual","Jalur sinyal, audio, listrik, dan keselamatan","Jadwal setup, rehearsal, dan dukungan teknis"],"process_eyebrow":"Alur kerja","process_title":"Tahapan yang disesuaikan dengan proyek.","process":["Meninjau rundown dan kebutuhan teknis","Survei venue serta jalur operasional","Menyiapkan perangkat dan sistem sinyal","Rehearsal serta operasional saat acara"],"portfolio_eyebrow":"Portofolio terkait","portfolio_title":"Lihat penerapannya pada proyek.","portfolio_link_text":"Semua proyek","cta_title":"Diskusikan kebutuhan acara Anda.","cta_description":"Sampaikan format acara, venue, jadwal, dan kebutuhan visual agar dukungan produksi dapat dibahas berdasarkan kebutuhan proyek.","cta_button_text":"Hubungi Visitiga","back_text":"Semua layanan"}'::jsonb,
  '{"eyebrow":"Event production service","title":"Event Production for Live Visual Experiences","description":"Visual and technical production support for events, stages, conferences, and live experiences, prepared from the rundown through show day.","intro_eyebrow":"Planning basis","intro_title":"A solution shaped by the event.","intro":"Event production brings together visual requirements, staging, signal, power, loading schedules, and technical support. Planning follows the venue and event flow so execution stays coordinated.","considerations_title":"What to confirm","considerations":["Event format and audience layout","Stage, screen, and visual requirements","Signal, audio, power, and safety routes","Setup, rehearsal, and technical support schedule"],"process_eyebrow":"Workflow","process_title":"Stages adapted to the project.","process":["Reviewing the rundown and technical needs","Surveying the venue and operating routes","Preparing equipment and signal systems","Rehearsal and live event operation"],"portfolio_eyebrow":"Related portfolio","portfolio_title":"See how it works in real projects.","portfolio_link_text":"All projects","cta_title":"Discuss your event requirements.","cta_description":"Share the event format, venue, schedule, and visual needs so production support can be planned around your project.","cta_button_text":"Contact Visitiga","back_text":"All services"}'::jsonb,
  'Event Production untuk Pengalaman Live | Visitiga', 'Dukungan produksi visual dan teknis untuk acara, panggung, konferensi, dan pengalaman live.',
  'Event Production for Live Visual Experiences | Visitiga', 'Visual and technical production support for events, stages, conferences, and live experiences.'
)
on conflict (slug) do nothing;

do $$
declare
  id_cards jsonb := jsonb_build_array(
    jsonb_build_object('title','Digital Signage','description','Solusi display terhubung untuk retail, hospitality, wayfinding, dan ruang bermerek.','tags',jsonb_build_array('Retail','Hospitality','Wayfinding'),'action','Konsultasi sekarang'),
    jsonb_build_object('title','Event Production','description','Dukungan produksi visual dan teknis untuk acara, panggung, konferensi, dan pengalaman live.','tags',jsonb_build_array('Events','Staging','Technical Support'),'action','Konsultasi sekarang')
  );
  en_cards jsonb := jsonb_build_array(
    jsonb_build_object('title','Digital Signage','description','Connected display solutions for retail, hospitality, wayfinding, and branded spaces.','tags',jsonb_build_array('Retail','Hospitality','Wayfinding'),'action','Consult now'),
    jsonb_build_object('title','Event Production','description','Visual and technical production support for events, stages, conferences, and live experiences.','tags',jsonb_build_array('Events','Staging','Technical Support'),'action','Consult now')
  );
begin
  update public.service_content
  set cards = case when cards @> jsonb_build_array(jsonb_build_object('title','Digital Signage')) then cards else cards || id_cards end,
      content_id = jsonb_set(content_id, '{cards}', case when content_id->'cards' @> jsonb_build_array(jsonb_build_object('title','Digital Signage')) then content_id->'cards' else content_id->'cards' || id_cards end, true),
      content_en = jsonb_set(content_en, '{cards}', case when content_en->'cards' @> jsonb_build_array(jsonb_build_object('title','Digital Signage')) then content_en->'cards' else content_en->'cards' || en_cards end, true)
  where id = 1;
end $$;
